cat > /tmp/audit.py <<'PY'
import subprocess, re, os, collections
REPO="/home/runner/monica-work"
branches=["rachel","monica","phoebe","joey","chandler","ross"]
def run(*a):
    return subprocess.run(["git","-C",REPO]+list(a),capture_output=True,text=True).stdout
spoken=[]
for b in branches:
    out=run("log","--format=%H%x1f%cI%x1f%s%x1f%b%x1e","origin/friend/"+b)
    for rec in out.split("\x1e"):
        rec=rec.strip("\n")
        if not rec.strip(): continue
        parts=rec.split("\x1f")
        if len(parts)<4: continue
        sha,date,subj,body=parts[0],parts[1],parts[2],parts[3]
        if not re.search(r'^Friend-Message: 1\s*$',body,re.M): continue
        m=re.search(r'^Episode:\s*(\S+)',body,re.M)
        ep=m.group(1) if m else "?"
        spoken.append((ep,date,sha,b,subj))
print("spoken utterances:",len(spoken))
# filed refs from main
files=run("ls-tree","-r","--name-only","origin/main").split("\n")
eps=[f for f in files if re.match(r'^S\d+/E\d+\.md$',f)]
filed=collections.defaultdict(set)
for f in eps:
    txt=run("show","origin/main:"+f)
    for m in re.finditer(r'^Source:\s*(\S+)\s*@\s*([0-9a-f]+)\s*$',txt,re.M):
        filed[f].add((m.group(1),m.group(2)))
print("filed refs:",sum(len(v) for v in filed.values()))
# map sha->episode
byep=collections.defaultdict(list)
for ep,date,sha,b,subj in spoken:
    byep[ep].append((sha,b,date))
missing=[]
for ep in sorted(byep):
    fn=ep.replace("S","S",1)
    path=ep+".md"
    have={s for br,s in filed.get(path,set())}
    for sha,b,date in sorted(byep[ep],key=lambda x:x[2]):
        if sha not in have:
            missing.append((path,sha,b,date))
print("MISSING from main:",len(missing))
for path,sha,b,date in missing[:40]:
    print(" ",path,date,b,sha)
# extras: filed refs that don't correspond to any real commit
allshas={sha for ep,date,sha,b,subj in spoken}
extra=[]
for path,refs in filed.items():
    for br,sha in refs:
        if sha not in allshas:
            extra.append((path,br,sha))
print("FILED-BUT-NOT-SPOKEN:",len(extra))
for path,br,sha in sorted(extra)[:40]:
    print(" ",path,br,sha)
