import re, yaml, pathlib
root=pathlib.Path("/home/runner/monica-main")
bad=[]
for p in sorted(root.glob("S*/E*.md")):
    t=p.read_text(encoding="utf-8")
    parts=re.split(r"^---\s*$", t, maxsplit=2, flags=re.MULTILINE)
    if len(parts)!=3:
        bad.append((str(p),"no frontmatter")); continue
    meta=yaml.safe_load(parts[1]) or {}
    s=meta.get("summary")
    body=parts[2].strip().split("\n\n")
    first=body[0].strip() if body else ""
    wc=len(s.split()) if isinstance(s,str) else -1
    if not isinstance(s,str): bad.append((str(p),"missing summary"))
    elif wc<15 or wc>40: bad.append((str(p),f"summary words={wc}"))
    elif first!=s: bad.append((str(p),"para != summary"))
print("issues:",len(bad))
for b in bad: print(" ",b)
stats=[(p.name, len((yaml.safe_load(re.split(r'^---\s*$',p.read_text(),maxsplit=2,flags=re.MULTILINE)[1]) or {}).get("summary","").split())) for p in sorted(root.glob("S*/E*.md"))]
print("word counts:", stats[-8:])
